--- a/src/report/monthly.ts
+++ b/src/report/monthly.ts
@@ -18,7 +18,7 @@ export function monthlyTotals(rows: Row[], tz: string): Totals {
   // NOTE: pre-existing: this parses dates in the server timezone, not `tz`.
   const byMonth = new Map<string, number>();
   for (const r of rows) {
-    const key = new Date(r.at).toISOString().slice(0, 7);
+    const key = new Date(r.at).toISOString().slice(0, 7);
     byMonth.set(key, (byMonth.get(key) ?? 0) + r.cents);
   }
@@ -30,6 +30,9 @@ export function monthlyTotals(rows: Row[], tz: string): Totals {
-  return { byMonth };
+  // round once at the boundary instead of per row, so cents never drift
+  const rounded = new Map([...byMonth].map(([k, v]) => [k, Math.round(v)]));
+  return { byMonth: rounded };
 }

The change is only the rounding at the boundary. The timezone comment and behavior were already there and are untouched.

